using Axiom.Gameplay;
namespace Game;
public sealed class InputApiLab : MonoBehaviour {
 public double Speed=3;[ReadOnly] public int SavedScore=0;[ReadOnly] public int Touches=0;[ReadOnly] public int Gamepads=0;[ReadOnly] public double MouseTravel=0;[ReadOnly] public string JumpControl="Space";
 private Vector3 origin;
 public override void Start(){origin=transform.position;SavedScore=PlayerPrefs.GetInt("score");if(PlayerPrefs.HasKey("inputBindings")){Input.LoadBindingOverridesFromJson(PlayerPrefs.GetString("inputBindings"));JumpControl=PlayerPrefs.GetString("jumpControl","Space");}Debug.Log("Input API Lab: WASD/arrows/gamepad left stick = move; Space/pad A = jump; J = switch Jump Space/Enter and save binding; P = increment and save score; R = reset. Touch/drag Game to position the cube. Stop/Play retains score and binding for this project/browser.");}
 public override void Update(){MouseTravel+=Input.MouseDelta.magnitude;Touches=Input.touchCount;Gamepads=Input.GetJoystickNames().Length;transform.position+=new Vector3(Input.GetAxisRaw("Horizontal"),0,-Input.GetAxisRaw("Vertical"))*Speed*Time.deltaTime;if(Input.GetButtonDown("Jump"))transform.position+=Vector3.up;if(Input.GetKeyDown(KeyCode.J)){JumpControl=JumpControl=="Space"?"Enter":"Space";Input.RebindButton("Jump",JumpControl,"Gamepad0/Button0");PlayerPrefs.SetString("inputBindings",Input.SaveBindingOverridesAsJson());PlayerPrefs.SetString("jumpControl",JumpControl);PlayerPrefs.Save();Debug.Log("Jump rebound and saved: "+JumpControl);}if(Input.GetKeyDown(KeyCode.P)){SavedScore++;PlayerPrefs.SetInt("score",SavedScore);PlayerPrefs.Save();Debug.Log("Saved score: "+SavedScore);}if(Input.GetKeyDown(KeyCode.R))transform.position=origin;if(Input.touchCount>0){var t=Input.GetTouch(0);if(t.phase is TouchPhase.Began or TouchPhase.Moved)transform.position=new Vector3((t.position.X-480)/100,1,(270-t.position.Y)/100);}}
}
